def nonoverlap_bbox(g):
 from collections import Counter
 co=Counter(x for row in g for x in row); col=min((x for x in co if x!=0),key=co.get); pts=[(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==col];r0=min(r for r,c in pts);c0=min(c for r,c in pts);s=[(r-r0,c-c0) for r,c in pts];h=max(r for r,c in s)+1;w=max(c for r,c in s)+1
 cs=[]
