def oriented_transform(g):
 from collections import Counter
 co=Counter(x for row in g for x in row); col=min((x for x in co if x!=0),key=co.get)
 ps=[(r,c) for r,row in enumerate(g) for c,x in enumerate(row) if x==col]
 base={(r-min(x for x,y in ps),c-min(y for x,y in ps)) for r,c in ps}
 masks=set()
 for reflect in [False,True]:
  q={(r, (max(c for _,c in base)-c) if reflect else c) for r,c in base}
  for k in range(4):
   p=q
   for _ in range(k):
    h=max(r for r,c in p)+1
    p={(c,h-1-r) for r,c in p}
   # normalized after rotation
   mr=min(r for r,c in p);mc=min(c for r,c in p);p=frozenset((r-mr,c-mc) for r,c in p)
   masks.add((p,max(r for r,c in p)+1,max(c for r,c in p)+1))
 out=[row[:] for row in g]
 for s,h,w in masks:
  for r in range(len(g)-h+1):
   for c in range(len(g[0])-w+1):
    if all(g[r+dr][c+dc]==0 for dr,dc in s):
     for dr,dc in s:out[r+dr][c+dc]=col
